def countMatches(items, ruleKey, ruleValue):
    # Step 1: Map ruleKey to index
    if ruleKey == "type":
        idx = 0
    elif ruleKey == "color":
        idx = 1
    elif ruleKey == "name":
        idx = 2
    else:
        # This shouldn't happen per problem constraints
        return 0

    match_count = 0
    # Step 2: Iterate over items and count matches
    for item in items:
        if item[idx] == ruleValue:
            match_count += 1
    return match_count
